css:
.meridiano-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e9e2d4;
    background: linear-gradient(180deg, #161310 0%, #100d0a 60%, #0a0807 100%);
    border-radius: 16px;
}

.meridiano-container * {
    box-sizing: border-box;
}

.meridiano-header {
    text-align: center;
    padding: 28px 22px 24px;
    background:
        radial-gradient(circle at 80% 0%, rgba(201, 162, 39, 0.18) 0%, transparent 55%),
        linear-gradient(135deg, #1a1611 0%, #221c12 55%, #2a2114 100%);
    color: #f6efdd;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #3a2f1a;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.55);
}

.meridiano-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f6e6b8;
    font-family: Georgia, 'Times New Roman', serif;
}

.meridiano-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #d8b54a;
    background: rgba(216, 181, 74, 0.10);
    border: 1px solid rgba(216, 181, 74, 0.32);
    padding: 5px 14px;
    border-radius: 4px;
}

.meridiano-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cabfa6;
}

.meridiano-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.94rem;
    font-weight: 600;
    color: #b6a988;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.meridiano-period-counter #currentDay,
.meridiano-period-counter #maxPeriods {
    font-weight: 800;
    color: #d8b54a;
}

.meridiano-round-name {
    background: rgba(216, 181, 74, 0.14);
    color: #e7c659;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.meridiano-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #e88a4a;
    background: rgba(232, 138, 74, 0.12);
    border: 1px solid rgba(232, 138, 74, 0.32);
    padding: 4px 12px;
    border-radius: 4px;
}

.meridiano-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 14px;
}

.meridiano-status-card {
    background: linear-gradient(160deg, #1d1813 0%, #15110d 100%);
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #322a1c;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.40);
    border-left: 4px solid #4a3f28;
}

.meridiano-card-esg { border-left-color: #4caf7d; }
.meridiano-card-te { border-left-color: #5a9bd4; }
.meridiano-card-var { border-left-color: #c66; }
.meridiano-card-sharpe { border-left-color: #d8b54a; }

.meridiano-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #9d9176;
}

.meridiano-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f6efdd;
    font-variant-numeric: tabular-nums;
    font-family: 'Consolas', 'SF Mono', Menlo, monospace;
}

.meridiano-card-esg .meridiano-value { color: #5fd49a; }
.meridiano-card-te .meridiano-value { color: #6fb0e8; }
.meridiano-card-var .meridiano-value { color: #e07a7a; }
.meridiano-card-sharpe .meridiano-value { color: #e7c659; }

.meridiano-sublabel {
    font-size: 0.75rem;
    color: #8a7f66;
    line-height: 1.35;
}

/* Breach / safe state highlighting */
.meridiano-breach {
    border-left-color: #ff4d4d !important;
    box-shadow: 0 0 0 1px rgba(255, 77, 77, 0.35), 0 6px 18px rgba(0, 0, 0, 0.40);
}
.meridiano-breach .meridiano-value { color: #ff5c5c !important; }
.meridiano-safe { border-left-color: #4caf7d !important; }
.meridiano-safe .meridiano-value { color: #5fd49a !important; }

.meridiano-secondary {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 18px;
}

.meridiano-carbon-bar,
.meridiano-cost-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14110c;
    border: 1px solid #322a1c;
    color: #cabfa6;
    padding: 10px 16px;
    border-radius: 8px;
    font-weight: 700;
    font-size: 0.86rem;
}

.meridiano-carbon-bar #carbonDisplay {
    font-size: 1.05rem;
    color: #e07a7a;
    font-family: 'Consolas', monospace;
}

.meridiano-carbon-bar.meridiano-carbon-ok #carbonDisplay {
    color: #5fd49a;
}

.meridiano-cost-bar #costDisplay {
    font-size: 1.05rem;
    color: #e88a4a;
    font-family: 'Consolas', monospace;
}

.meridiano-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #1d1813 0%, #15110d 100%);
    border-left: 5px solid #d8b54a;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.meridiano-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.meridiano-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f6e6b8;
    margin-bottom: 6px;
}

.meridiano-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #cabfa6;
}

.meridiano-briefing-text strong { color: #e7c659; }
.meridiano-briefing-text em { color: #e88a4a; font-style: italic; }

.meridiano-controls {
    background: linear-gradient(160deg, #181410 0%, #110e0a 100%);
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #322a1c;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.meridiano-controls h3 {
    margin: 0 0 16px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #f6e6b8;
    border-bottom: 2px solid #322a1c;
    padding-bottom: 8px;
}

.meridiano-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #ddd0b3;
    margin: 14px 0 6px;
}

.meridiano-container select,
.meridiano-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #443a25;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #14110c;
    color: #f1e9d6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.meridiano-container select:focus,
.meridiano-container input[type="number"]:focus {
    outline: none;
    border-color: #d8b54a;
    box-shadow: 0 0 0 3px rgba(216, 181, 74, 0.20);
}

.meridiano-container select option {
    background-color: #14110c;
    color: #f1e9d6;
}

.meridiano-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #d8b54a;
}

.meridiano-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #b6a988;
    margin-top: 4px;
}

.meridiano-range-readout span:nth-child(2) {
    color: #e7c659;
    font-weight: 800;
    font-family: 'Consolas', monospace;
}

.meridiano-hint {
    font-size: 0.8rem;
    color: #8a7f66;
    margin-top: 5px;
    line-height: 1.45;
}

.meridiano-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.meridiano-container .btn-primary {
    background: linear-gradient(135deg, #a9851f 0%, #e7c659 100%);
    border: none;
    color: #1c1607;
    padding: 11px 28px;
    border-radius: 7px;
    box-shadow: 0 8px 20px rgba(169, 133, 31, 0.40);
}

.meridiano-container .btn-primary:hover {
    filter: brightness(1.07);
}

.meridiano-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #443a25;
    color: #b6a988;
    background: transparent;
}

.meridiano-coach {
    background: linear-gradient(160deg, #14110c 0%, #1a140d 100%);
    color: #ddd0b3;
    border: 1px solid #3a2f1a;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.meridiano-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d8b54a;
    margin-bottom: 8px;
}

.meridiano-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.meridiano-coach-body strong { color: #e7c659; }
.meridiano-coach-body em { color: #e88a4a; font-style: italic; }

.meridiano-history,
.meridiano-chart {
    background: linear-gradient(160deg, #181410 0%, #110e0a 100%);
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #322a1c;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.meridiano-history h3,
.meridiano-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    color: #f6e6b8;
}

.meridiano-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.86rem;
    color: #ddd0b3;
}

.meridiano-container table#usfHistoryTable th {
    background: #14110c;
    color: #d8b54a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.5px;
    padding: 8px 10px;
    border-bottom: 2px solid #443a25;
}

.meridiano-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2a2418;
    color: #cabfa6;
    font-variant-numeric: tabular-nums;
}

.meridiano-container table#usfHistoryTable tr:nth-child(even) td {
    background: #161109;
}

.meridiano-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .meridiano-container {
        padding: 14px;
    }
    .meridiano-header h1 {
        font-size: 1.7rem;
    }
    .meridiano-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .meridiano-value {
        font-size: 2.05rem;
    }
    .meridiano-secondary {
        grid-template-columns: 1fr;
    }
    .meridiano-clock {
        margin-left: 0;
    }
    .meridiano-period-counter {
        font-size: 0.86rem;
    }
    .meridiano-carbon-bar,
    .meridiano-cost-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .meridiano-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .mer-cm-*) */
.mer-cm { margin-top: 8px; }
.mer-cm-incomplete { text-align: center; color: #322a1c; font-size: 1rem; padding: 18px; }
.mer-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.mer-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #14110c 0%, #322a1c 45%, #d8b54a 150%); color: #f6e6b8; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(20,17,12,0.30); }
.mer-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; color: #ffffff; }
.mer-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.mer-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #e7c659; }
.mer-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fbf4de; border: 1px solid #ddd0b3; border-radius: 14px; padding: 14px 20px; }
.mer-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #8a7a52; }
.mer-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #322a1c; margin-top: 4px; line-height: 1.15; }
.mer-cm-section { margin-bottom: 16px; }
.mer-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #9a7d2e; margin-bottom: 8px; border-bottom: 1px solid #ddd0b3; padding-bottom: 4px; }
.mer-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.mer-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.mer-cm-ok { background: #eef3df; color: #4d5a1f; border-color: #cfe0a8; }
.mer-cm-no { background: #f7e6dc; color: #a8531f; border-color: #edc7ac; }
.mer-cm-ico { font-weight: 800; }
.mer-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.mer-cm-kpi { background: #fffdf6; border: 1px solid #ddd0b3; border-radius: 12px; padding: 12px 10px; text-align: center; }
.mer-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #9a7d2e; line-height: 1; }
.mer-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #322a1c; margin-top: 6px; }
.mer-cm-kpi-sub { font-size: 0.68rem; color: #8a7a52; margin-top: 2px; }
.mer-cm-insights { margin: 0; padding-left: 20px; color: #14110c; }
.mer-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .mer-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

