        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.esgHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                meridianoChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.esgHistory },
                        { data: ds.teHistory },
                        { data: ds.varHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const esg = ds.esg, te = ds.te, vaR = ds.var, sharpe = ds.sharpe, carbon = ds.carbon, cost = ds.cost;

            const esgOk = esg >= this.ESG_FLOOR;
            const teOk = te <= this.TE_CAP;
            const varOk = vaR <= this.VAR_CAP;
            const carbonOk = carbon <= 0;
            const allCleared = esgOk && teOk && varOk && carbonOk;

            // Composite: all four constraints cleared, plus a Sharpe bonus and a cost penalty.
            const cleared = [esgOk, teOk, varOk, carbonOk].filter(Boolean).length;
            const sharpeScore = Math.max(0, Math.min(40, (sharpe - 0.4) * 100));   // 0.4->0, 0.8->40
            const costPenalty = Math.min(20, cost / 4);                            // up to -20 for heavy trading
            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_review`;
            if (allCleared && sharpe >= 0.62 && !ds.mandateAtRisk && composite >= 75) tierKey = `grade_responsibility`;
            else if (allCleared && !ds.mandateAtRisk) tierKey = `grade_retained`;
            else if (te > this.TE_CAP && esgOk) tierKey = `grade_teblown`;
            else if (vaR > this.VAR_CAP) tierKey = `grade_varbreach`;
            else if (cost >= 50) tierKey = `grade_overtraded`;
            else if (cleared >= 2) tierKey = `grade_partial`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (allCleared && !ds.mandateAtRisk && sharpe >= 0.62) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (!esgOk) insights.push(window.mySimulation.t(`insight_esgunfixed`));
            else if (te > this.TE_CAP) insights.push(window.mySimulation.t(`insight_teblown`));
            else if (vaR > this.VAR_CAP) insights.push(window.mySimulation.t(`insight_varbreach`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (carbon > 0) insights.push(window.mySimulation.t(`insight_carbon`));
            if (cost >= 40) insights.push(window.mySimulation.t(`insight_cost`));
            if (sharpe < 0.55) insights.push(window.mySimulation.t(`insight_sharpe`));
            if (ds.mandateAtRisk) insights.push(window.mySimulation.t(`insight_mandate`));
            if (allCleared && sharpe >= 0.62 && cost < 30) insights.push(window.mySimulation.t(`insight_efficient`));

            return {
                esg: esg,
                te: te,
                var: vaR,
                sharpe: sharpe,
                carbon: carbon,
                cost: cost,
                cleared: cleared,
                allCleared: allCleared,
                mandateAtRisk: ds.mandateAtRisk,
                esgOk: esg >= this.ESG_FLOOR,
                teOk: te <= this.TE_CAP,
                varOk: vaR <= this.VAR_CAP,
                carbonOk: carbon <= 0,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="mer-cm"><p class="mer-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="mer-cm-chip ` + (ok ? `mer-cm-ok` : `mer-cm-no`) + `">` +
                `<span class="mer-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
