                (sub ? `<div class="mer-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="mer-cm">` +
  `<div class="mer-cm-head">` +
    `<div class="mer-cm-score"><div class="mer-cm-score-num">` + Math.round(s.composite) +
