    `<div class="mer-cm-verdict"><div class="mer-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="mer-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="mer-cm-section"><div class="mer-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="mer-cm-chips">` + chip(!!s.esgOk, t(`cm_t_esg`)) + chip(!!s.teOk, t(`cm_t_te`)) +
      chip(!!s.varOk, t(`cm_t_var`)) + chip(!!s.carbonOk, t(`cm_t_carbon`)) + `</div></div>` +
  `<div class="mer-cm-section"><div class="mer-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="mer-cm-kpis">` +
      kpi(t(`cm_lbl_esg`), Math.round(s.esg), t(`cm_sub_esg`)) +
      kpi(t(`cm_lbl_te`), Number(s.te).toFixed(2) + `%`, t(`cm_sub_te`)) +
      kpi(t(`cm_lbl_var`), Number(s.var).toFixed(2) + `%`, t(`cm_sub_var`)) +
      kpi(t(`cm_lbl_sharpe`), Number(s.sharpe).toFixed(2), t(`cm_sub_sharpe`)) +
    `</div></div>` +
  (insights ? `<div class="mer-cm-section"><div class="mer-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="mer-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.esg < this.ESG_FLOOR && state.currentPeriod >= 2) return window.mySimulation.t(`hint_esg`);
            if (ds.te > this.TE_CAP) return window.mySimulation.t(`hint_te`);
            if (ds.var > this.VAR_CAP) return window.mySimulation.t(`hint_var`);
            if (ds.carbon > 0 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_carbon`);
            if (ds.cost >= 40) return window.mySimulation.t(`hint_cost`);
            if (ds.esg >= this.ESG_FLOOR && ds.te <= this.TE_CAP && ds.var <= this.VAR_CAP && ds.carbon <= 0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

